CHECK={
 1:{'k5':("A recipe has 100 letters. The copier gets 1 in every 100 wrong. After one copy, how many letters are wrong?",1,'n',.02,"1 out of every 100, and there are 100.","Right. About 1 wrong letter."),
    'g8':("A gene is 1,000 letters long and the error rate is 1 in 10,000 per letter per copy. Copy it 50 times. Expected mistakes?",5,'n',.02,"letters × rate × copies.","Right. 1,000 × 0.0001 × 50 = 5."),
    'hs':("Error rate 2% per letter per copy. What percent of a letter's copies are still correct after 10 copies? (0.98¹⁰)",81.7,'%',.03,"Multiply 0.98 by itself ten times.","Right. About 82%: after ten copies nearly one letter in five has changed."),
    'col':("About 10⁻⁸ mutations per base per generation, and 6 × 10⁹ bases in a diploid genome. New mutations per child?",60,'n',.05,"Rate × bases.","Right. About 60, and sequencing of families finds about that many."),
    'max':("Polymerase errs once per 10⁵ bases; proofreading removes 99 of 100 errors; mismatch repair removes 99 of 100 of what is left. Errors per 10⁹ bases?",1,'n',.05,"10⁻⁵ × 10⁻² × 10⁻² per base.","Right. 10⁻⁹ per base, so about 1 per billion.")},
 2:{'k5':("50 pale moths and 50 dark moths sit on sooty bark. The bird eats 30 pale and 5 dark. How many pale moths are left?",20,'n',.02,"50 take away 30.","Right. 20 pale moths, and 45 dark ones."),
    'g8':("Of 50 pale moths, 30 were eaten. What percent of the pale moths survived?",40,'%',.02,"20 survived out of 50.","Right. 40%."),
    'hs':("Pale moths survive 40% of the time, dark 90%. Start with 50 of each. After one round, what percent of the survivors are dark?",69.2,'%',.03,"20 pale and 45 dark survive.","Right. 45 out of 65 is about 69%."),
    'col':("Relative fitness of pale is 0.44 and of dark is 1. Dark is at frequency 0.3. New dark frequency after selection? p′ = p·w_dark ÷ (p·w_dark + q·w_pale)",49.3,'%',.03,"0.3 ÷ (0.3 + 0.7 × 0.44).","Right. About 49%: from 30% to nearly half in one generation."),
    'max':("Selection coefficient s = 0.1 per generation, haploid. Generations for the favoured type to go from 1% to 50%? (ln(p/q) changes by s each generation)",46,'gen',.05,"ln(99) ÷ 0.1.","Right. About 46 generations.")},
 3:{'k5':("Two Tt pea plants have 4 babies. How many do you expect to be tall?",3,'n',.02,"Three out of every four.","Right. 3 tall, 1 short, on average."),
    'g8':("Tt × Tt gives 400 plants. Expected short plants?",100,'n',.02,"One in four is tt.","Right. 100 short."),
    'hs':("TtRr × TtRr gives 160 plants. Expected tall-and-round (the 9 in 9 : 3 : 3 : 1)?",90,'n',.02,"9 out of 16.","Right. 90."),
    'col':("A recessive trait appears in 4% of a population in Hardy–Weinberg equilibrium. What percent are carriers (2pq)?",32,'%',.02,"q² = 0.04 so q = 0.2 and p = 0.8.","Right. 32%: eight times as many carriers as affected."),
    'max':("Tt × Tt gives 290 tall and 110 short out of 400. Expected 300 and 100. χ² = ?",1.333,'n',.05,"Σ (observed − expected)² ÷ expected.","Right. 0.33 + 1 = 1.33, well under the 3.84 needed to doubt the ratio.")},
 4:{'k5':("One germ splits into 2 every 20 minutes. Start with 1. How many after 1 hour?",8,'cells',.02,"Three doublings.","Right. 1, 2, 4, 8."),
    'g8':("Doubling every 20 minutes, starting with 10 cells. How many after 2 hours?",640,'cells',.02,"Six doublings: 10 × 2⁶.","Right. 640."),
    'hs':("Doubling time 30 minutes. How long to go from 1 cell to about a million (2²⁰)?",10,'h',.03,"20 doublings × 30 minutes.","Right. 600 minutes is 10 hours."),
    'col':("Doubling time 20 minutes. Growth rate r = ln 2 ÷ T, in per hour?",2.08,'/h',.03,"T is a third of an hour.","Right. About 2.08 per hour."),
    'max':("Mutation to resistance at 10⁻⁷ per cell division. A culture grows from 1 to 10⁸ cells. Expected number of mutation events?",10,'n',.05,"About 10⁸ divisions × 10⁻⁷.","Right. About 10, so resistance was there before the drug.")},
 5:{'k5':("An island has 20 animals: 5 red and 15 blue. What percent are red?",25,'%',.02,"5 out of 20.","Right. 25%."),
    'g8':("Ten animals: 3 red, 7 blue. Each baby copies a random parent's colour. Expected red among 10 babies?",3,'n',.02,"Same share as the parents, on average.","Right. 3, but real draws wobble around it."),
    'hs':("A neutral colour is carried by 1 animal out of 50. Chance it eventually takes over the whole island?",2,'%',.02,"Its current frequency.","Right. 2%, and a 98% chance it is lost."),
    'col':("100 gene copies (50 diploid animals), p = 0.5. Standard deviation of next generation's frequency, √(pq ÷ 100), in percent?",5,'%',.03,"√(0.25 ÷ 100).","Right. 5 points per generation, and it adds up."),
    'max':("Heterozygosity decays by (1 − 1/2N) per generation. N = 10 diploid. What percent remains after 20 generations?",35.8,'%',.03,"0.95²⁰.","Right. About 36%: two-thirds of the variation gone in twenty generations.")},
 6:{'k5':("Cat and lion have 1 difference out of 10. Cat and fish have 8. How many more differences does the fish have?",7,'n',.02,"8 take away 1.","Right. 7 more: the lion is the closer cousin."),
    'g8':("Two species differ at 12 of 100 letters. Changes come at 1 letter per million years on each line. How long ago did they split?",6,'Myr',.03,"Each line collected half the differences.","Right. 6 million years, 6 changes on each side."),
    'hs':("Species A and B differ at 20 letters. The clock ticks at 2 letters per million years per lineage. Split age?",5,'Myr',.03,"20 ÷ (2 × 2).","Right. 5 million years."),
    'col':("Observed fraction of differing sites p = 0.30. Jukes–Cantor corrected distance d = −¾·ln(1 − 4p/3)?",0.383,'n',.03,"ln(0.6) is about −0.51.","Right. About 0.38, more than the 0.30 you see, because some sites changed twice."),
    'max':("Five species. How many rooted binary trees are possible? ((2n − 3)!!)",105,'n',.02,"7 × 5 × 3 × 1.","Right. 105. For twenty species it is 8 × 10²¹.")},
}
FIG={
 1:'''<div class="panel"><canvas id="cv-copy" aria-label="A DNA recipe of 24 letters copied generation after generation, with copying mistakes highlighted."></canvas></div>
    <div class="controls"><button class="btn primary" id="cp-copy">Copy it</button><button class="btn" id="cp-ten">Copy ×10</button><button class="btn" id="cp-proof" aria-pressed="false">Proofreading: off</button><label class="slider">Error rate <input type="range" id="cp-err" min="0.5" max="10" step="0.5" value="3"><span class="val" id="cp-err-val">3% per letter</span></label><button class="btn" id="cp-reset">New recipe</button></div>
    <figcaption><b>Try this:</b> copy the recipe ten times and count the mistakes. Then turn the error rate up and copy until half the letters are wrong. Then turn proofreading on and try again.</figcaption>''',
 2:'''<div class="panel"><canvas id="cv-moth" aria-label="Moths of many shades resting on bark. You are the bird: click the ones you can see before the time runs out. Survivors breed."></canvas></div>
    <div class="controls"><button class="btn primary" id="mo-go">Start a round</button><button class="btn" id="mo-auto" aria-pressed="false">Automatic bird: off</button><button class="btn" id="mo-run">Run 20 generations</button><label class="slider">Bark soot <input type="range" id="mo-soot" min="0" max="1" step="0.05" value="0.1"><span class="val" id="mo-soot-val">10%</span></label><button class="btn" id="mo-reset">Reset</button></div>
    <figcaption><b>Try this:</b> hunt for a few rounds on clean bark. Then soot the bark and hunt again, and watch the average darkness climb. Then clean it. <span data-lv="col max">Then set the bark to grey and let the automatic bird run: stabilizing selection.</span></figcaption>''',
 3:'''<div class="panel"><canvas id="cv-pea" aria-label="Two parent pea plants, a Punnett square, and a growing tally of tall and short offspring drawn at random."></canvas></div>
    <div class="controls"><span class="lbl">Parent 1</span><button class="btn" data-p1="TT">TT</button><button class="btn is-on" data-p1="Tt">Tt</button><button class="btn" data-p1="tt">tt</button><span class="lbl">Parent 2</span><button class="btn" data-p2="TT">TT</button><button class="btn is-on" data-p2="Tt">Tt</button><button class="btn" data-p2="tt">tt</button><button class="btn primary" id="pe-1">Grow 1</button><button class="btn" id="pe-10">Grow 10</button><button class="btn" id="pe-100">Grow 100</button><button class="btn" id="pe-reset">Clear</button></div>
    <figcaption><b>Try this:</b> grow four plants from Tt × Tt, then a hundred. Watch the count settle near three tall to one short. Then find the crosses that give half and half, and all tall.</figcaption>''',
 4:'''<div class="panel"><canvas id="cv-germ" aria-label="A dish of bacteria doubling over time, with a growth curve. Antibiotic buttons kill sensitive cells; resistant mutants survive."></canvas></div>
    <div class="controls"><button class="btn primary" id="bc-run" aria-pressed="false">Run</button><button class="btn" id="bc-a" aria-pressed="false">Antibiotic A: off</button><button class="btn" id="bc-b" data-lv="hs col max" aria-pressed="false">Antibiotic B: off</button><label class="slider">Doubling time <input type="range" id="bc-T" min="10" max="60" step="5" value="20"><span class="val" id="bc-T-val">20 min</span></label><button class="btn" id="bc-fluct" data-lv="col max">Fluctuation test</button><button class="btn" id="bc-reset">New dish</button></div>
    <figcaption><b>Try this:</b> run until the dish is full, then dose with A until it is empty. Then fill a new dish, dose for a while, stop early, and watch what grows back. <span data-lv="hs col max">Then use A and B together.</span></figcaption>''',
 5:'''<div class="panel"><canvas id="cv-drift" aria-label="An island of red and blue animals. Each generation every animal copies a random parent's colour. A graph tracks the red fraction."></canvas></div>
    <div class="controls"><button class="btn primary" id="dr-step">Next generation</button><button class="btn" id="dr-run" aria-pressed="false">Run: off</button><button class="btn" id="dr-storm">Storm: 5 survive</button><label class="slider">Animals <input type="range" id="dr-n" min="10" max="200" step="10" value="10"><span class="val" id="dr-n-val">10</span></label><button class="btn" id="dr-ten" data-lv="col max">Run 10 islands</button><button class="btn" id="dr-reset">Reset</button></div>
    <figcaption><b>Try this:</b> run ten animals until one colour is gone. Then two hundred. Then hit the storm and watch the mix jump.</figcaption>''',
 6:'''<div class="panel"><canvas id="cv-tree" aria-label="Five creatures with their DNA shown as coloured stripes. Click two to say they are the closest cousins; correct joins build the family tree."></canvas></div>
    <div class="controls"><button class="btn primary" id="tr-new">New puzzle</button><button class="btn" id="tr-show">Show the answer</button><label class="slider" data-lv="hs col max">Clock rate <input type="range" id="tr-rate" min="1" max="4" step="1" value="2"><span class="val" id="tr-rate-val">2 changes per Myr</span></label></div>
    <figcaption><b>Try this:</b> click the two creatures whose stripes match best. If you are right they join. Keep joining until one tree holds all five. <span data-lv="hs col max">Read the split ages off the scale.</span></figcaption>''',
}
